"""Supplier and portfolio PDF reports, generated by a background task under row level security."""

from __future__ import annotations

import re
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

import structlog

from app.container import Container
from app.services import pdf, portfolio, profile

log = structlog.get_logger()
_SAFE_ID = re.compile(r"^[0-9a-f-]{36}$")


def _fmt_date(value: Any) -> str:
    return value.strftime("%Y-%m-%d") if hasattr(value, "strftime") else str(value or "")


def supplier_sections(data: dict[str, Any]) -> list[str]:
    sup, comp, risk = data["supplier"], data["company"], data["risk"]
    conf = "" if sup["confidence"] is None else " (confidence {:.2f})".format(sup["confidence"])
    parts = [f"<h2>Summary</h2><p>Supplier as uploaded: <b>{pdf.esc(sup['uploaded_name'])}</b>. "
             f"Resolution status: {pdf.esc(sup['status'])}{conf}.</p>"]
    if risk:
        parts.append(f"<p>Risk score <b>{risk['score']:.1f}</b> "
                     f"(<span class='lvl'>{pdf.esc(risk['level'])}</span>), configuration "
                     f"{pdf.esc(risk['config_version'])}, computed {_fmt_date(risk['computed_at'])}.</p>")
    else:
        parts.append("<p>No risk score has been computed for this supplier.</p>")
    if comp:
        ids = [("CIK", comp.get("cik")), ("LEI", comp.get("lei")), ("Wikidata", comp.get("wikidata_qid")),
               ("Tickers", ", ".join(comp.get("tickers") or []) or None)]
        parts.append("<h2>Resolved identity</h2>" + pdf.table(
            ["Field", "Value"], [["Canonical name", comp["canonical_name"]],
                                 ["Headquarters", ", ".join(x for x in (comp.get("hq_city"), comp.get("hq_state")) if x)],
                                 *[[k, v] for k, v in ids if v],
                                 ["Known aliases", "; ".join(a["alias"] for a in comp["aliases"][:10])]]))
    else:
        parts.append("<h2>Resolved identity</h2><p>This supplier is not resolved to a canonical company.</p>")
    fam = data["family"]
    if fam and fam["nodes"]:
        parts.append("<h2>Corporate family</h2>" + pdf.table(
            ["Company", "Relation", "Hops", "In portfolio"],
            [[n["name"], "parent side" if n["direction"] == "up" else "subsidiary side", n["hop"],
              "yes" if n["in_portfolio"] else "no"] for n in fam["nodes"]], num_cols=(2,)))
        parts.append("<p class='meta'>Sources: " + pdf.esc(", ".join(sorted({e["source"] for e in fam["edges"]})))
                     + ".</p>")
    ev_rows = [[_fmt_date(e["reported_at"]), e["source"], e["event_type"].replace("_", " "), e["severity"],
                e["title"], e["relation"].replace("_", " "), e.get("url") or ""] for e in data["events"][:25]]
    parts.append("<h2>Events</h2><p class='meta'>Each row states what the named public record says, with its "
                 "source and record date. Records are not findings of fault.</p>" + pdf.table(
                     ["Record date", "Source", "Type", "Sev.", "Record", "Reaches supplier as", "Link"],
                     ev_rows, num_cols=(3,), widths=(13, 7, 12, 5, 30, 14, 19), url_cols=(6,)))
    if risk:
        parts.append("<h2>Score breakdown</h2>" + pdf.table(
            ["Event", "Category", "Severity w.", "Recency", "Link conf.", "Relation w.", "Reliability", "Impact"],
            [[c["title"], c["category"].replace("_", " "), f"{c['severity_weight']:.2f}",
              f"{c['recency_decay']:.2f}", f"{c['link_confidence']:.2f}", f"{c['relation_weight']:.2f}",
              f"{c['source_reliability']:.2f}", f"{c['event_impact']:.3f}"] for c in risk["components"]],
            num_cols=(2, 3, 4, 5, 6, 7)))
        if risk["category_scores"]:
            parts.append(pdf.table(["Category", "Sub-score"], [[k.replace("_", " "), v]
                                                                for k, v in risk["category_scores"].items()],
                                   num_cols=(1,)))
    if data["sources"]:
        parts.append("<h2>Sources of the canonical record</h2>" + pdf.table(
            ["Source", "Key", "Link method", "Score"],
            [[s["source"], s["source_key"], s["method"], f"{s['score']:.2f}"] for s in data["sources"][:20]],
            num_cols=(3,)))
    return parts


def portfolio_sections(conn: Any) -> list[str]:
    status = conn.execute("SELECT status, count(*) AS n FROM suppliers WHERE duplicate_of IS NULL "
                          "GROUP BY status ORDER BY status").fetchall()
    levels = conn.execute(
        "SELECT rs.level, count(*) AS n FROM suppliers s JOIN LATERAL (SELECT level FROM risk_scores r "
        "WHERE r.supplier_id = s.id ORDER BY computed_at DESC, id DESC LIMIT 1) rs ON true "
        "WHERE s.duplicate_of IS NULL GROUP BY rs.level").fetchall()
    top = conn.execute(
        "SELECT s.uploaded_name, co.canonical_name, rs.score, rs.level FROM suppliers s "
        "JOIN LATERAL (SELECT score, level FROM risk_scores r WHERE r.supplier_id = s.id "
        "ORDER BY computed_at DESC, id DESC LIMIT 1) rs ON true "
        "LEFT JOIN companies co ON co.id = s.resolved_company_id WHERE s.duplicate_of IS NULL "
        "ORDER BY rs.score DESC LIMIT 15").fetchall()
    ev = conn.execute(
        "SELECT e.event_type, count(DISTINCT e.id) AS n FROM events e JOIN event_entities ee ON ee.event_id = e.id "
        "JOIN suppliers s ON s.resolved_company_id = ee.company_id WHERE ee.route = 'accepted' "
        "AND e.reported_at >= now() - interval '90 days' GROUP BY 1 ORDER BY n DESC").fetchall()
    pending = conn.execute("SELECT count(*) AS n FROM resolution_reviews WHERE status = 'open'").fetchone()["n"]
    conc = portfolio.concentration(conn, top=10)
    return [
        "<h2>Portfolio</h2>" + pdf.table(["Resolution status", "Suppliers"], [[r["status"], r["n"]] for r in status],
                                         num_cols=(1,)) + f"<p>Reviews awaiting a decision: {pending}.</p>",
        "<h2>Suppliers by risk level</h2>" + pdf.table(["Level", "Suppliers"], [[r["level"], r["n"]] for r in levels],
                                                       num_cols=(1,)),
        "<h2>Highest scores</h2>" + pdf.table(
            ["Supplier", "Canonical company", "Score", "Level"],
            [[r["uploaded_name"], r["canonical_name"], f"{float(r['score']):.1f}", r["level"]] for r in top],
            num_cols=(2,)),
        "<h2>Events reaching the portfolio, last 90 days</h2>" + pdf.table(
            ["Event type", "Events"], [[r["event_type"].replace("_", " "), r["n"]] for r in ev], num_cols=(1,)),
        "<h2>Concentration by ultimate parent</h2>" + pdf.table(
            ["Parent company", "Suppliers", "Share", "High or critical", "Cumulative"],
            [[g["name"], g["suppliers"], f"{g['share_of_suppliers']:.0%}", g["high_risk_suppliers"],
              f"{g['cumulative_share']:.0%}"] for g in conc["groups"]], num_cols=(1, 2, 3, 4)),
    ]


def generate_report(c: Container, tenant_id: str, report_id: str) -> None:
    """Render and store the PDF, then mark the report ready (or failed with a reason)."""
    if not _SAFE_ID.match(report_id) or not _SAFE_ID.match(tenant_id):
        raise ValueError("invalid identifier")
    try:
        with c.db.tenant(tenant_id) as conn:
            rep = conn.execute("SELECT * FROM reports WHERE id = %s", (report_id,)).fetchone()
            if rep is None:
                return
            now = datetime.now(UTC)
            if rep["kind"] == "supplier":
                sup = conn.execute("SELECT * FROM suppliers WHERE id = %s", (rep["supplier_id"],)).fetchone()
                title = f"Supplier risk report: {sup['uploaded_name']}"
                sections = supplier_sections(profile.supplier_profile(conn, sup))
            else:
                title = "Portfolio risk report"
                sections = portfolio_sections(conn)
        doc = pdf.document(title, report_id, now.strftime("%Y-%m-%d %H:%M UTC"), sections,
                           c.settings.demo_mode)
        data = pdf.render_pdf(doc)
        folder = Path(c.settings.report_dir) / tenant_id
        folder.mkdir(parents=True, exist_ok=True)
        path = folder / f"{report_id}.pdf"
        path.write_bytes(data)
        with c.db.tenant(tenant_id) as conn:
            conn.execute("UPDATE reports SET status = 'ready', storage_path = %s, completed_at = now(), "
                         "error = NULL WHERE id = %s", (str(path), report_id))
    except Exception as exc:  # the failure is recorded for the user, not hidden
        log.error("report_failed", report_id=report_id, error_type=type(exc).__name__)
        with c.db.tenant(tenant_id) as conn:
            conn.execute("UPDATE reports SET status = 'failed', error = %s, completed_at = now() "
                         "WHERE id = %s", (f"{type(exc).__name__}: {str(exc)[:300]}", report_id))
